{
  "name": "A2D源测电源板",
  "name_en": "A2D Source-Measure Power Board",
  "manufacturer": "A2D",
  "description": "这是一块可编程电源与测量一体化电路板，可输出设定电压或电流，并测量电压、电流及板载温度。它适合实验室中用于为被测器件供电、进行基础电学表征、校准与板级调试。",
  "description_en": "This is a programmable power and measurement board that can source a set voltage or current and measure voltage, current, and onboard temperature. It is suitable for laboratory use in powering devices under test, basic electrical characterization, calibration, and board-level debugging.",
  "tag_hints": [
    "source measure unit",
    "programmable power supply",
    "voltage and current measurement",
    "board-level testing",
    "electrical calibration",
    "I2C-configurable analog front end",
    "temperature monitoring"
  ],
  "actions": [
    {
      "action_name": "auto-calibrate_current",
      "description": "校准电流测量或输出通道。",
      "description_en": "Calibrate the current measurement or output channel."
    },
    {
      "action_name": "auto-calibrate_voltage",
      "description": "校准电压测量或输出通道。",
      "description_en": "Calibrate the voltage measurement or output channel."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化电源板并使其进入可工作状态。",
      "description_en": "Initialize the power board and place it into an operational state."
    },
    {
      "action_name": "auto-measure_current",
      "description": "测量当前输出或被测回路中的电流。",
      "description_en": "Measure the current in the output or connected circuit."
    },
    {
      "action_name": "auto-measure_temperature",
      "description": "测量电源板温度。",
      "description_en": "Measure the temperature of the power board."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量当前输出或被测节点的电压。",
      "description_en": "Measure the voltage at the output or connected node."
    },
    {
      "action_name": "auto-reset_calibration",
      "description": "将校准数据恢复为默认状态。",
      "description_en": "Reset the calibration data to its default state."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置输出电流设定值。",
      "description_en": "Set the output current setpoint."
    },
    {
      "action_name": "auto-set_i2c_adc_addr",
      "description": "设置板上 ADC 的 I2C 地址。",
      "description_en": "Set the I2C address of the onboard ADC."
    },
    {
      "action_name": "auto-set_i2c_dac_addr",
      "description": "设置板上 DAC 的 I2C 地址。",
      "description_en": "Set the I2C address of the onboard DAC."
    },
    {
      "action_name": "auto-set_led",
      "description": "设置板载指示灯开关状态。",
      "description_en": "Set the on/off state of the onboard indicator LED."
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置输出电压设定值。",
      "description_en": "Set the output voltage setpoint."
    },
    {
      "action_name": "auto-toggle_output",
      "description": "打开或关闭电源板输出。",
      "description_en": "Enable or disable the power board output."
    }
  ]
}

